<?php if(!$activity): ?><div class="member-empty"><?= icon('activity',28) ?><h3>Hesabınızın hikâyesi burada başlayacak.</h3><p>Sipariş ve destek durumlarınız güncellendiğinde burada görebilirsiniz.</p><a class="member-btn is-soft" href="/kategoriler">Hizmetleri keşfet</a></div><?php else: ?><div class="member-activity-list"><?php foreach($activity as $event): ?><a href="<?= e($event['url']) ?>" class="member-event"><span class="member-event-icon"><?= icon($event['kind']==='support'?'headphones':'package',18) ?></span><div><strong><?= e($event['title']) ?></strong><p><?= e($event['detail']) ?></p><time><?= formatDate($event['date'],'d.m.Y H:i') ?></time></div><?= icon('chevron-right',16) ?></a><?php endforeach; ?></div><?php endif; ?>
